[CmdletBinding(SupportsShouldProcess=$true)]
param([Parameter(Mandatory=$true)][string]$PackageRoot,[Parameter(Mandatory=$true)][string]$ProjectRoot,[ValidateSet("Upgrade")][string]$Mode="Upgrade")
$ErrorActionPreference="Stop";$p=(Resolve-Path -LiteralPath $PackageRoot).Path;$r=(Resolve-Path -LiteralPath $ProjectRoot).Path;$src=Join-Path $p "static";$dst=Join-Path $r "backend\src\palwakf_local_agents\command_center\static";$files=@("index.html","styles.css","app.js");foreach($f in $files){foreach($x in @((Join-Path $src $f),(Join-Path $dst $f))){if(-not(Test-Path -LiteralPath $x -PathType Leaf)){throw "REQUIRED_STATIC_FILE_NOT_FOUND=$x"}}};$stamp=Get-Date -Format "yyyyMMddHHmmss";$backup=Join-Path $r "backups\command_center_operational_ui_ux_read_only_v1_$stamp";$manifest=Join-Path $backup "install_preimage_manifest.json"
if($WhatIfPreference){foreach($f in $files){$t=Join-Path $dst $f;$b=Join-Path $backup (Join-Path "preimage\static" $f);if($PSCmdlet.ShouldProcess($b,"Backup current Command Center static asset")){Copy-Item $t $b -Force};if($PSCmdlet.ShouldProcess($t,"Install operational read-only UI asset")){Copy-Item (Join-Path $src $f) $t -Force}};"INSTALL_STATUS=WHATIF_COMPLETE";"INSTALL_MODE=$Mode";"BACKUP_PATH=$backup";"BACKUP_MANIFEST_PATH=$manifest";"BACKUP_STATUS=PLANNED";"INSTALL_BACKUP_STRATEGY=EXACT_STATIC_ASSET_PREIMAGE_COPY";"UI_MUTATION_SCOPE=STATIC_ASSETS_ONLY";"STATIC_ASSET_COUNT=3";"APP_ENTRYPOINT_MUTATION=NONE";"ROUTER_MUTATION=NONE";"STORE_MUTATION=NONE";"API_MUTATION=NONE";"MODEL_EXECUTION=NONE";"PILOT_EXECUTION=NOT_EXECUTED";"PROJECT_MUTATION=PLANNED_STATIC_ASSETS_ONLY";exit 0}
New-Item -ItemType Directory -Path (Join-Path $backup "preimage\static") -Force|Out-Null;$pre=@();foreach($f in $files){$s=Join-Path $src $f;$t=Join-Path $dst $f;$b=Join-Path $backup (Join-Path "preimage\static" $f);Copy-Item $t $b -Force;$pre+=[ordered]@{relative_path="static/$f";source_sha256=(Get-FileHash $s -Algorithm SHA256).Hash;preimage_sha256=(Get-FileHash $t -Algorithm SHA256).Hash}};$o=[ordered]@{package_id='MEGA_BATCH_COMMAND_CENTER_OPERATIONAL_UI_UX_READ_ONLY_V1';created_at_local=(Get-Date).ToString('o');install_mode=$Mode;patch_scope='STATIC_ASSETS_ONLY';assets=$pre;app_entrypoint_mutation='NONE';router_mutation='NONE';store_mutation='NONE';api_mutation='NONE';model_execution='NONE';pilot_execution='NOT_EXECUTED'};$o|ConvertTo-Json -Depth 6|Set-Content $manifest -Encoding UTF8;$hashes=@();foreach($f in $files){$s=Join-Path $src $f;$t=Join-Path $dst $f;Copy-Item $s $t -Force;$sh=(Get-FileHash $s -Algorithm SHA256).Hash;$th=(Get-FileHash $t -Algorithm SHA256).Hash;if($sh -ne $th){throw "STATIC_ASSET_INSTALL_HASH_MISMATCH=$f"};$hashes+="$f=$th"};"INSTALL_STATUS=COMPLETE";"INSTALL_MODE=$Mode";"BACKUP_PATH=$backup";"BACKUP_MANIFEST_PATH=$manifest";"BACKUP_STATUS=COMPLETE";"INSTALL_BACKUP_STRATEGY=EXACT_STATIC_ASSET_PREIMAGE_COPY";"STATIC_ASSET_HASHES=$($hashes -join ';')";"UI_MUTATION_SCOPE=STATIC_ASSETS_ONLY";"STATIC_ASSET_COUNT=3";"APP_ENTRYPOINT_MUTATION=NONE";"ROUTER_MUTATION=NONE";"STORE_MUTATION=NONE";"API_MUTATION=NONE";"TASK_STATE_MUTATION=NONE";"MODEL_EXECUTION=NONE";"PILOT_EXECUTION=NOT_EXECUTED";"PLATFORM_MUTATION=NONE";"DATABASE_ACCESS=NONE";"GIT_WRITE=NONE";"DEPLOYMENT=NONE";"SECRETS_ACCESS=NONE";"MEMORY_WRITE=NONE";"PROJECT_MUTATION=STATIC_ASSETS_ONLY";"NEXT_STEP=RUN_STATIC_GATE_UNITTEST_ROUTE_PROBE_AND_BROWSER_UAT";exit 0